native_time_probe.reproducible_probe_source:
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <string>
#include <thread>
#include <vector>
#include "kirin_hypha_ffi.h"
#include "kirin_hypha_abi_contract.h"
using Clock=std::chrono::steady_clock;
namespace fs=std::filesystem;
int main(int argc,char**argv) {
  if(argc!=4)return 2;
  const std::string root=argv[1]; const double duration=std::stod(argv[2]),phase=std::stod(argv[3]);
  if(root.rfind("/tmp/hypha-g0-native-",0)!=0)return 3;
  fs::create_directories(root+"/tmp");fs::create_directories(root+"/home");
  setenv("KIRIN_HYPHA_TEST_STORAGE_ROOT",root.c_str(),1);
  KirinAbiContract abi{};kirin_hypha_abi_contract(&abi);
  bool ok=abi.revision==KIRIN_ABI_REVISION&&abi.meter_history_entry_size==sizeof(KirinMeterHistoryEntry)
    &&abi.meter_history_entry_epoch_offset==offsetof(KirinMeterHistoryEntry,measurement_epoch)
    &&abi.meter_session_size==sizeof(KirinMeterSession)&&abi.measure_result_size==sizeof(KirinMeasureResult);
  std::cout<<"{\"kind\":\"abi\",\"revision\":"<<abi.revision<<",\"header_revision\":"<<KIRIN_ABI_REVISION
    <<",\"meter_history_size\":"<<abi.meter_history_entry_size<<",\"meter_session_size\":"<<abi.meter_session_size<<",\"match\":"<<(ok?"true":"false")<<"}\n";
  if(!ok)return 4;
  const uint8_t roles[]={KIRIN_CHANNEL_ROLE_LEFT,KIRIN_CHANNEL_ROLE_RIGHT};
  auto*pre=kirin_hypha_create(48000,roles,2);auto*post=kirin_hypha_create(48000,roles,2);if(!pre||!post)return 5;
  const char*preId="aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";const char*postId="bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
  for(auto*h:{pre,post})kirin_hypha_set_license(h,0);
  kirin_hypha_set_identity(pre,preId,"cccccccc-cccc-4ccc-8ccc-cccccccccccc","dddddddd-dddd-4ddd-8ddd-dddddddddddd","G0-probe");
  kirin_hypha_set_identity(post,postId,"cccccccc-cccc-4ccc-8ccc-cccccccccccc","dddddddd-dddd-4ddd-8ddd-dddddddddddd","G0-probe");
  kirin_hypha_enable_pre_writes(pre);kirin_hypha_enable_post_writes(post);kirin_hypha_set_pair_target(post,"G0-probe");
  const auto start=Clock::now();auto seconds=[&](){return std::chrono::duration<double>(Clock::now()-start).count();};
  std::vector<float>samples(960);uint64_t frames=0,accepted=0,rejected=0;double nextFeed=0,nextPoll=phase,nextDiscovery=0,nextPair=0;
  std::map<std::string,fs::path>paths;std::map<std::string,fs::file_time_type>stamps;std::map<std::string,int64_t>lastEndpoint;
  std::map<std::string,std::set<int64_t>>seen;
  bool selected=false;double observerTotalMs=0,observerMaxMs=0,feedLateTotalMs=0,feedLateMaxMs=0;uint64_t observerTicks=0,feedTicks=0;
  while(seconds()<duration) {
    const auto now=seconds();
    if(now>=nextFeed) {
      const double lateMs=(now-nextFeed)*1000;feedLateTotalMs+=lateMs;feedLateMaxMs=std::max(feedLateMaxMs,lateMs);++feedTicks;
      for(size_t i=0;i<480;++i){const float s=0.1f*std::sin(2*3.141592653589793*997*(frames+i)/48000.0);samples[i*2]=s;samples[i*2+1]=s;}
      for(auto*h:{pre,post}) {
        kirin_hypha_set_signal_state(h,KIRIN_SIGNAL_STATE_ACTIVE);
        kirin_hypha_note_capture_window(h,true,frames,480,KIRIN_HYPHA_CLOCK_PROJECT_TIMELINE,KIRIN_HYPHA_PRESENTATION_SOURCE_VST3,true,0,true,0,KIRIN_HYPHA_AUXILIARY_SOURCE_UNKNOWN,false,0,false);
        if(kirin_hypha_push_samples(h,samples.data(),480,2))++accepted;else ++rejected;
      }
      frames+=480;nextFeed=static_cast<double>(frames)/48000;
      if(frames%4800==0)std::cout<<"{\"kind\":\"input_slot_supplied\",\"wall_s\":"<<seconds()<<",\"endpoint_samples\":"<<frames<<",\"feed_lateness_ms\":"<<lateMs<<"}\n";
    }
    if(!selected&&now>=nextPair){selected=kirin_hypha_select_pair_candidate(post,preId);nextPair=now+0.05;if(selected)std::cout<<"{\"kind\":\"pair_selected\",\"wall_s\":"<<seconds()<<"}\n";}
    if(paths.size()<3&&now>=nextDiscovery) {
      const fs::path base=root+"/tmp/kirin";
      if(fs::exists(base))for(auto const&entry:fs::recursive_directory_iterator(base))if(entry.is_regular_file()) {
        const auto name=entry.path().filename().string();const auto parent=entry.path().parent_path().filename().string();
        if(parent==preId&&name=="meter_history.json")paths["pre_history_publication"]=entry.path();
        if(parent==preId&&name=="pre.json")paths["pre_watch_publication"]=entry.path();
        if(parent==postId&&name=="post.json")paths["post_watch_publication"]=entry.path();
      }
      nextDiscovery=now+0.02;
    }
    const double observerStart=seconds();
    for(const auto&[kind,path]:paths) {
      std::error_code err;const auto stamp=fs::last_write_time(path,err);if(err|| (stamps.count(kind)&&stamps[kind]==stamp))continue;stamps[kind]=stamp;
      if(kind=="pre_history_publication") {
        std::ifstream input(path);std::string content((std::istreambuf_iterator<char>(input)),{});int64_t endpoint=-1;
        size_t pos=0;while((pos=content.find("\"endpoint_samples\"",pos))!=std::string::npos){pos=content.find(':',pos)+1;while(pos<content.size()&&(content[pos]==' '||content[pos]=='\n'||content[pos]=='\t'))++pos;
          char* end=nullptr;const auto point=std::strtoll(content.c_str()+pos,&end,10);pos=end-content.c_str();endpoint=std::max<int64_t>(endpoint,point);
          if(seen[kind].insert(point).second)std::cout<<"{\"kind\":\"pre_publication_first_endpoint\",\"wall_s\":"<<seconds()<<",\"endpoint_samples\":"<<point<<"}\n";}
        if(endpoint>=0&&endpoint!=lastEndpoint[kind]){lastEndpoint[kind]=endpoint;std::cout<<"{\"kind\":\""<<kind<<"\",\"wall_s\":"<<seconds()<<",\"endpoint_samples\":"<<endpoint<<",\"audio_age_ms\":"<<(seconds()-static_cast<double>(endpoint)/48000)*1000<<"}\n";}
      }else std::cout<<"{\"kind\":\""<<kind<<"\",\"wall_s\":"<<seconds()<<"}\n";
    }
    const double observerMs=(seconds()-observerStart)*1000;observerTotalMs+=observerMs;observerMaxMs=std::max(observerMaxMs,observerMs);++observerTicks;
    if(now>=nextPoll) {
      const double pollAt=seconds();
      for(const auto&[kind,handle]:std::vector<std::pair<std::string,KirinHypha*>>{{"pre_native_history",pre},{"post_native_history",post},{"delta_native_history",post}}){
        KirinMeterHistoryEntry out[64]{};uint32_t count=0;
        const bool polled=kind=="delta_native_history"?kirin_hypha_poll_meter_delta_history(handle,0,out,64,&count):kirin_hypha_poll_meter_history(handle,0,out,64,&count);
        const int64_t endpoint=count?out[count-1].last_timeline_endpoint_samples:-1;
        for(uint32_t i=0;i<count;++i){const auto point=out[i].last_timeline_endpoint_samples;if(point>=0&&seen[kind].insert(point).second)
          std::cout<<"{\"kind\":\""<<kind<<"_first_endpoint\",\"wall_s\":"<<pollAt<<",\"endpoint_samples\":"<<point<<"}\n";}
        std::cout<<"{\"kind\":\""<<kind<<"\",\"wall_s\":"<<pollAt<<",\"success\":"<<(polled?"true":"false")<<",\"count\":"<<count
          <<",\"endpoint_samples\":"<<endpoint<<",\"observed_frames\":"<<(count?out[count-1].last_observed_frames:0)<<",\"finite_psr\":"<<(count&&std::isfinite(out[count-1].psr.mean)?"true":"false")
          <<",\"audio_age_ms\":"<<(endpoint>=0?(pollAt-static_cast<double>(endpoint)/48000)*1000:-1)<<"}\n";
      }
      nextPoll+=0.1;
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(2));
  }
  std::cout<<"{\"kind\":\"end\",\"accepted_transactions\":"<<accepted<<",\"rejected_transactions\":"<<rejected<<",\"pair_status\":"<<(int)kirin_hypha_pair_status(post)<<",\"duration_s\":"<<seconds()<<",\"observer_sleep_ms\":2,\"observer_mean_ms\":"<<observerTotalMs/observerTicks<<",\"observer_max_ms\":"<<observerMaxMs<<",\"feed_lateness_mean_ms\":"<<feedLateTotalMs/feedTicks<<",\"feed_lateness_max_ms\":"<<feedLateMaxMs<<"}\n";
  kirin_hypha_set_signal_state(pre,0);kirin_hypha_set_signal_state(post,0);kirin_hypha_destroy(post);kirin_hypha_destroy(pre);
}
